// Debug: Show ALL tasks and their details
const tasks = $input.first().json.result || [];
console.log(`\n=== KANBOARD TASK ANALYSIS ===`);
console.log(`Total tasks found: ${tasks.length}`);

if (tasks.length === 0) {
  console.log('❌ No tasks found in Kanboard!');
  return [{ json: { error: 'No tasks found', total_tasks: 0 } }];
}

// Show details of each task
tasks.forEach((task, index) => {
  console.log(`\n--- Task ${index + 1} ---`);
  console.log(`ID: ${task.id}`);
  console.log(`Title: "${task.title}"`);
  console.log(`Description: "${task.description}"`);
  console.log(`Status ID: ${task.status_id}`);
  console.log(`Project ID: ${task.project_id}`);
  console.log(`Date Created: ${task.date_creation}`);
});

// Return first few tasks for file checking
const tasksToCheck = tasks.slice(0, 3); // Check first 3 tasks
console.log(`\n🔍 Will check files for first ${tasksToCheck.length} tasks`);

return tasksToCheck.map(task => ({
  json: {
    task_id: parseInt(task.id),
    title: task.title,
    description: task.description,
    status_id: task.status_id
  }
}));

// Detailed file analysis
const taskData = $input.first().json;
const fileResponse = $input.last().json;

console.log(`\n🔍 ANALYZING FILES FOR TASK ${taskData.task_id}`);
console.log(`Task Title: "${taskData.title}"`);
console.log(`Raw Kanboard Response:`);
console.log(JSON.stringify(fileResponse, null, 2));

const files = fileResponse.result || [];
console.log(`\n📁 Files found: ${files.length}`);

if (files.length === 0) {
  console.log(`❌ No files attached to task ${taskData.task_id}`);
  return {
    json: {
      task_id: taskData.task_id,
      task_title: taskData.title,
      status: 'NO_FILES',
      files_count: 0,
      message: 'No files attached to this task'
    }
  };
}

// Analyze each file in detail
const fileAnalysis = files.map((file, index) => {
  console.log(`\n--- File ${index + 1} ---`);
  console.log(`Name: "${file.name}"`);
  console.log(`ID: ${file.id}`);
  console.log(`Size: ${file.size} bytes`);
  console.log(`MIME Type: ${file.mimetype || 'not specified'}`);
  console.log(`Token: ${file.token}`);
  console.log(`Date: ${file.date}`);
  console.log(`User ID: ${file.user_id}`);

  // Check if it's a PDF
  const isPdfByName = file.name && file.name.toLowerCase().endsWith('.pdf');
  const isPdfByMime = file.mimetype && file.mimetype.toLowerCase().includes('pdf');

  console.log(`Is PDF by name: ${isPdfByName}`);
  console.log(`Is PDF by MIME: ${isPdfByMime}`);

  const downloadUrl = `/index.php?controller=FileController&action=download&file_id=${file.id}&token=${file.token}`;
  console.log(`Download URL: http://localhost:8000${downloadUrl}`);

  return {
    name: file.name,
    id: file.id,
    size: file.size,
    mimetype: file.mimetype,
    token: file.token,
    download_url: downloadUrl,
    is_pdf_by_name: isPdfByName,
    is_pdf_by_mime: isPdfByMime,
    is_pdf: isPdfByName || isPdfByMime
  };
});

const pdfFiles = fileAnalysis.filter(f => f.is_pdf);
console.log(`\n✅ PDF files detected: ${pdfFiles.length}`);
pdfFiles.forEach(pdf => {
  console.log(`- ${pdf.name} (${pdf.size} bytes)`);
});

return {
  json: {
    task_id: taskData.task_id,
    task_title: taskData.title,
    status: files.length > 0 ? 'HAS_FILES' : 'NO_FILES',
    files_count: files.length,
    pdf_count: pdfFiles.length,
    all_files: fileAnalysis,
    pdf_files: pdfFiles,
    first_pdf: pdfFiles.length > 0 ? pdfFiles[0] : null
  }
};
